import {PILOT_FORMS,pilotAssignment} from './pilot-kit.js';
export const SESSION_KEY='fixiverse-guided-session-v1',SESSION_DAY=86400000;
export const sessionChoices=focus=>focus==='Fraction'?['left','equal','right','unsure','help','skip','not offered']:['sun','leaf','star','moon','unsure','help','skip','not offered'];
export const newGuidedSession=()=>({version:1,stage:'setup'});
const fail=()=>{throw Error('This testing-session record is invalid. Keep a backup before making changes.');};
export function restoreGuidedSession(raw){
 const s=structuredClone(raw);if(!s||s.version!==1||!['setup','before','play','after','waiting','nextday','complete'].includes(s.stage))fail();if(s.stage==='setup')return newGuidedSession();
 if(!['Fraction','Pattern'].includes(s.focus)||!Number.isInteger(s.planIndex)||s.planIndex<0||s.planIndex>7||!s.device||!s.browser||!['Actual device','Browser viewport simulation','Not specified'].includes(s.environment)||!Number.isFinite(s.createdAt)||!s.phases||!s.play)fail();
 for(const key of ['device','browser','input','tools','prior','notes'])if(typeof s[key]!=='string'||s[key].length>1000)fail();
 if(!s.play||!(s.play.started===null||Number.isFinite(s.play.started)&&s.play.started>=s.createdAt)||!(s.play.finished===null||Number.isFinite(s.play.finished)&&s.play.started!==null&&s.play.finished>=s.play.started)||!['Not run','Partial','Complete'].includes(s.play.completeness)||typeof s.play.note!=='string'||s.play.note.length>1000||!(s.play.observation===null||typeof s.play.observation==='string'&&s.play.observation.length<=80))fail();
 for(const [key,p]of Object.entries(s.phases)){if(!['before','after','nextday'].includes(key)||!['A','B','C'].includes(p.form)||p.form!==pilotAssignment(s.planIndex)[{before:'Before',after:'After',nextday:'Next-day'}[key]]||!Number.isFinite(p.started)||!Array.isArray(p.answers)||p.answers.length>3||![null,'skip',1,2,3].includes(p.confidence)||!(p.finished===null||Number.isFinite(p.finished)&&p.finished>=p.started))fail();for(const a of p.answers)if(!sessionChoices(s.focus).includes(a.response)||!Number.isInteger(a.help)||a.help<0||a.help>3||!(a.supported===''||sessionChoices(s.focus).includes(a.supported))||typeof a.access!=='string'||a.access.length>1000||!Number.isFinite(a.at))fail();if(p.finished!==null&&(p.answers.length!==3||p.confidence===null))fail();}
 for(const p of Object.values(s.phases)){if(p.answers.length&&p.confidence===null)fail();if(p.corrections!==undefined&&(!Array.isArray(p.corrections)||p.corrections.length>20||p.corrections.some(c=>!Number.isInteger(c.task)||c.task<1||c.task>3||typeof c.reason!=='string'||!c.reason.trim()||c.reason.length>1000||!Number.isFinite(c.at)||!sessionChoices(s.focus).includes(c.previous?.response)||!Number.isInteger(c.previous?.help)||c.previous.help<0||c.previous.help>3)))fail();}
 if(!s.phases.before||s.stage!=='before'&&s.phases.before.finished===null)fail();
 if(['after','waiting','nextday','complete'].includes(s.stage)&&(s.play.finished===null||!s.phases.after))fail();if(['waiting','nextday','complete'].includes(s.stage)&&s.phases.after?.finished==null)fail();if(s.phases.nextday&&s.phases.nextday.started-s.phases.after.finished<SESSION_DAY)fail();if(s.stage==='complete'&&s.phases.nextday?.finished==null)fail();
 return s;
}
export function guidedStep(old,a,now=Date.now()){
 const s=restoreGuidedSession(old),text=x=>String(x||'').trim().slice(0,1000);if(!Number.isFinite(now)||now<0||s.createdAt&&now<s.createdAt)throw Error('Check the device clock.');
 const begin=key=>{s.stage=key;s.phases[key]={form:pilotAssignment(s.planIndex)[{before:'Before',after:'After',nextday:'Next-day'}[key]],started:now,finished:null,confidence:null,answers:[],note:''};};
 if(a.type==='setup'){if(s.stage!=='setup')throw Error('The plan is already started.');Object.assign(s,{focus:a.focus,planIndex:+a.planIndex,device:text(a.device),browser:text(a.browser),input:text(a.input),tools:text(a.tools),environment:a.environment,prior:text(a.prior),notes:'',createdAt:now,phases:{},play:{started:null,finished:null,observation:null,completeness:'Not run',note:''}});begin('before');}
 else if(a.type==='confidence'){const p=s.phases[s.stage];if(!p||p.finished!==null||p.confidence!==null||![1,2,3,'skip'].includes(a.value))throw Error('Choose an unanswered confidence question.');p.confidence=a.value;}
 else if(a.type==='answer'){const p=s.phases[s.stage];if(!p||p.confidence===null||p.finished!==null||p.answers.length>=3)throw Error('Record confidence before these tasks.');if(!sessionChoices(s.focus).includes(a.response)||!Number.isInteger(a.help)||a.help<0||a.help>3)throw Error('Choose a response and help level.');p.answers.push({response:a.response,help:a.help,access:text(a.access),supported:'',at:now});}
 else if(a.type==='correct-last'){const p=s.phases[s.stage];if(!p||p.finished!==null||!p.answers.length||!text(a.reason))throw Error('Record a reason to correct the last entry before finishing this phase.');p.corrections??=[];if(p.corrections.length>=20)throw Error('Too many corrections. Export this record and review it with your tutor.');p.corrections.push({task:p.answers.length,previous:p.answers.pop(),reason:text(a.reason),at:now});}
 else if(a.type==='finish-phase'){const p=s.phases[s.stage];if(!p||p.answers.length!==3||p.confidence===null||p.finished!==null)throw Error('Record all tasks, including any not offered.');for(let i=0;i<3;i++){const value=a.supported?.[i]||'';if(value&&!sessionChoices(s.focus).includes(value))throw Error('Choose a supported response.');p.answers[i].supported=value;}p.note=text(a.note);p.finished=now;if(s.stage==='before')s.stage='play';else if(s.stage==='after')s.stage='waiting';else s.stage='complete';}
 else if(a.type==='play'){if(s.stage!=='play')throw Error('The before tasks must finish first.');s.play.started??=now;if(a.observation)s.play.observation=a.observation;}
 else if(a.type==='finish-play'){if(s.stage!=='play'||s.play.started===null)throw Error('Start the play visit first.');if(!['Complete','Partial','Not run'].includes(a.completeness))throw Error('Describe observation completeness.');s.play.finished=now;s.play.completeness=a.completeness;s.play.note=text(a.note);begin('after');}
 else if(a.type==='nextday'){if(s.stage!=='waiting'||now-s.phases.after.finished<SESSION_DAY)throw Error('The next-day tasks unlock 24 hours after the after tasks finish.');begin('nextday');}
 else throw Error('Unknown session action.');return restoreGuidedSession(s);
}
export function phaseResult(s,key){const p=s.phases?.[key];if(!p)return null;const tasks=PILOT_FORMS[p.form][s.focus],offered=p.answers.filter(a=>a.response!=='not offered').length;return{offered,recorded:p.answers.length,complete:p.finished!==null&&offered===3,first:p.answers.reduce((n,a,i)=>n+Number(a.response===tasks[i].answer&&a.help===0),0),supported:p.answers.some(a=>a.supported)?p.answers.reduce((n,a,i)=>n+Number((a.supported||a.response)===tasks[i].answer),0):null,help:p.answers.length?Math.max(...p.answers.map(a=>a.help)):null,confidence:typeof p.confidence==='number'?p.confidence:null};}
const cleanCSV=v=>{if(typeof v==='number'&&Number.isFinite(v))return String(v);let s=String(v??'');if(/^\s*[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};
export const sessionCSV=rows=>rows.map(r=>r.map(cleanCSV).join(',')).join('\r\n');
export function guidedRows(entries){
 const summary=[['Learner','Focus','Before /3','After /3','Next-day /3','After minus before','Next-day minus before','Confidence before','Confidence after','Confidence next-day','Hours after to next-day','Stage','Device','Browser','Tools','Confidence after minus before','UI instructions logged in play','Math-help marks in play','Access-support marks in play','Unresolved blockers in play','Play observation completeness']],sessions=[['Learner','Focus','Phase','Form','Started ISO','Finished ISO','Tasks offered','First correct without math help','Supported final correct','Confidence','Top math help','Access support','Notes','Observation completeness']],answers=[['Learner','Focus','Phase','Form','Task','Task description','First response','Math help before response','Access support','Supported response','Recorded ISO']];
 for(const {alias,model,observations}of entries){if(!model||model.stage==='setup')continue;const s=restoreGuidedSession(model),visit=observations?.sessions?.find(v=>v.id===s.play.observation),marks=visit?.events?.filter(v=>!v.voided)||[],count=k=>visit?marks.filter(v=>v.kind===k).reduce((n,v)=>n+v.quantity,0):'',b=phaseResult(s,'before'),a=phaseResult(s,'after'),n=phaseResult(s,'nextday'),score=p=>p?.complete?p.first:'';summary.push([alias,s.focus,score(b),score(a),score(n),b?.complete&&a?.complete?a.first-b.first:'',b?.complete&&n?.complete?n.first-b.first:'',b?.confidence??'',a?.confidence??'',n?.confidence??'',s.phases.nextday?((s.phases.nextday.started-s.phases.after.finished)/3600000).toFixed(2):'',s.stage,s.device,s.browser,s.tools,b?.confidence!=null&&a?.confidence!=null?a.confidence-b.confidence:'',count('UI instruction'),count('Math help'),count('Access support'),visit?marks.filter(v=>v.severity==='Blocker'&&v.status!=='Retested').length:'',s.play.completeness]);
 for(const key of ['before','after','nextday']){const p=s.phases[key];if(!p)continue;const r=phaseResult(s,key);sessions.push([alias,s.focus,key,p.form,new Date(p.started).toISOString(),p.finished===null?'':new Date(p.finished).toISOString(),r.offered,p.finished===null?'':r.first,r.supported??'',p.confidence??'',r.help??'',p.answers.map(a=>a.access).filter(Boolean).join(' | '),p.note,'']);p.answers.forEach((v,i)=>{const t=PILOT_FORMS[p.form][s.focus][i];answers.push([alias,s.focus,key,p.form,i+1,t.pair?`1/${t.pair[0]} vs 1/${t.pair[1]}`:`${t.block.join('/')} loop; ${t.length} tiles`,v.response,v.help,v.access,v.supported,new Date(v.at).toISOString()]);});}
 if(s.play.started!==null)sessions.push([alias,s.focus,'play','',new Date(s.play.started).toISOString(),s.play.finished===null?'':new Date(s.play.finished).toISOString(),'','','','','','',s.play.note,s.play.completeness]);
 }return{summary,sessions,answers};
}
export function sessionWorkbook(sheets){const xml=x=>String(x??'').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));return'<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Default"><Alignment ss:Vertical="Top" ss:WrapText="1"/><Font ss:FontName="Arial" ss:Size="11"/></Style><Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#355641" ss:Pattern="Solid"/></Style></Styles>'+Object.entries(sheets).map(([name,rows])=>`<Worksheet ss:Name="${xml(name)}"><Table><Column ss:Width="150" ss:Span="${Math.max(...rows.map(r=>r.length))-1}"/>${rows.map((r,i)=>'<Row>'+r.map(v=>`<Cell ss:StyleID="${i===0?'Header':'Default'}"><Data ss:Type="${typeof v==='number'?'Number':'String'}">${xml(v)}</Data></Cell>`).join('')+'</Row>').join('')}</Table></Worksheet>`).join('')+'</Workbook>';}

